    'programs.rogersProject.desc': 'Lidera un proyecto de integración IT del mundo real inspirado en la fusión de telecomunicaciones Rogers-Shaw de $26B.',
    'programs.rogersProject.prereq': 'Requiere completar cursos específicos para desbloquear',
