    'founder.bio.title': '敏捷与AI教育的远见领导者',
    'founder.bio.p1': 'Didier是一位经验丰富的IT高管和敏捷转型领导者，拥有多年推动邮轮、酒店和企业领域大规模技术计划的经验。目前担任皇家加勒比国际公司IT敏捷技术项目经理，他策划跨全球运营的数百万美元数字化转型项目。',
