    'programs.badge': 'Nos Programmes',
    'programs.title': 'Programmes de Formation de Classe Mondiale',
    'programs.subtitle': 'Des cours complets conçus pour élever vos compétences professionnelles.',
    'programs.scrum.title': 'Cours de Certification Scrum Master',
    'programs.scrum.desc': 'Devenez Scrum Master certifié avec une formation pratique et des méthodologies d\'apprentissage améliorées par l\'IA.',
    'programs.pm.title': 'Project Management Professional',
    'programs.pm.desc': 'Maîtrisez les cadres de gestion de projet avec des outils IA modernes pour la planification et l\'exécution.',
    'programs.cyber.title': 'Professionnel en Cybersécurité',
    'programs.cyber.desc': 'Maîtrisez les fondamentaux de la cybersécurité, l\'analyse des menaces, le hacking éthique et les opérations de sécurité alimentées par l\'IA. Préparez-vous pour CompTIA Security+ et CISSP.',
