    'programs.subtitle': 'Umfassende Kurse, die Ihre beruflichen Fähigkeiten und Karrierechancen verbessern.',
    'programs.scrum.title': 'Scrum Master Zertifizierungskurs',
    'programs.scrum.desc': 'Werden Sie zertifizierter Scrum Master mit praxisnahem Training und KI-gestützten Lernmethoden.',
    'programs.pm.title': 'Project Management Professional',
    'programs.pm.desc': 'Meistern Sie Projektmanagement-Frameworks mit modernen KI-Tools für Planung und Ausführung.',
    'programs.cyber.title': 'Cybersecurity Professional',
    'programs.cyber.desc': 'Meistern Sie Cybersecurity-Grundlagen, Bedrohungsanalyse, ethisches Hacking und KI-gestützte Sicherheitsoperationen. Bereiten Sie sich auf CompTIA Security+ und CISSP vor.',
    'programs.architect.title': 'Solution Architect',
    'programs.architect.desc': 'Entwerfen Sie Cloud- und On-Premise-Architekturen auf Unternehmensebene. Meistern Sie AWS, Azure, Microservices und KI-gestützte Systemdesignmuster.',
    'programs.data.title': 'Data Analytics Professional',
    'programs.data.desc': 'Verwandeln Sie Rohdaten in Geschäftseinblicke mit Python, SQL, Power BI und KI-gestützter Analytik. Von Dashboards bis zu Vorhersagemodellen.',
    'programs.devops.title': 'DevOps & Cloud Engineering',
    'programs.devops.desc': 'Meistern Sie CI/CD-Pipelines, Kubernetes, Docker, Infrastructure as Code und KI-unterstützte DevOps-Praktiken.',
    'programs.ba.title': 'Business Analysis Professional',
    'programs.ba.desc': 'Verbinden Sie Business und Technologie mit fortgeschrittener Anforderungstechnik, Prozessmodellierung und KI-gestützten Analysetools.',
    'programs.ai.title': 'KI-Tools für Manager',
