    'programs.title': 'Программы обучения мирового класса',
    'programs.subtitle': 'Комплексные курсы, разработанные для повышения ваших профессиональных навыков и карьерных перспектив в гибком управлении проектами.',
    'programs.scrum.title': 'Курс сертификации Scrum Master',
    'programs.scrum.desc': 'Станьте сертифицированным Scrum Master с практическим обучением, реальными проектами и методологиями обучения на базе ИИ.',
    'programs.pm.title': 'Профессионал по управлению проектами',
    'programs.pm.desc': 'Освойте фреймворки управления проектами с современными инструментами ИИ для планирования, выполнения и управления стейкхолдерами.',
    'programs.cyber.title': 'Профессионал по кибербезопасности',
    'programs.cyber.desc': 'Освойте основы кибербезопасности, анализ угроз, этичный хакинг и операции безопасности на базе ИИ. Подготовка к CompTIA Security+ и CISSP.',
    'programs.architect.title': 'Архитектор решений',
    'programs.architect.desc': 'Проектируйте облачные и локальные архитектуры корпоративного уровня. Освойте AWS, Azure, микросервисы и шаблоны системного дизайна на базе ИИ.',
    'programs.data.title': 'Профессионал по аналитике данных',
    'programs.data.desc': 'Превращайте сырые данные в бизнес-инсайты с помощью Python, SQL, Power BI и аналитики на базе ИИ. От дашбордов до прогнозных моделей.',
    'programs.devops.title': 'DevOps и облачная инженерия',
