    'about.badge': 'О нас',
    'about.title': 'Основано на совершенстве',
    'about.p1': 'Aladiah Academy была основана с чёткой целью: преодолеть разрыв между традиционным образованием в области управления проектами и быстро развивающимися требованиями современного делового мира.',
    'about.p2': 'Под руководством нашего основателя, опытного профессионала, работающего в Royal Caribbean International, мы привносим реальный опыт и отраслевые связи в каждую предлагаемую нами программу.',
    'about.p3': 'Работая под руководством Aladiah Management, мы поддерживаем высочайшие стандарты профессионального обучения, одновременно принимая инновации и преобразующую силу ИИ в образовании.',
